import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { gunzipSync } from "node:zlib";
import { transformSync } from "esbuild";
import { API } from "typescript/unstable/sync";
import { createVirtualFileSystem } from "typescript/unstable/fs";
import * as ast from "typescript/unstable/ast";
import {
  historicalObjectAnnotations,
  historicalSubjectApp,
  objectGovernanceHistory,
  type ArchivedSource,
} from "./object-annotations-governance-history.js";

// Immutable original migration evidence only; the current APIs never read it.
const encoded =
  "";
export const humanPrivateGovernanceHistory = JSON.parse(
  gunzipSync(Buffer.from(encoded, "base64")).toString(),
) as { sources: Record<string, ArchivedSource> };
for (const value of Object.values(humanPrivateGovernanceHistory.sources)) {
  assert.equal(Buffer.byteLength(value.raw), value.bytes);
  assert.equal(
    createHash("sha256").update(value.raw).digest("hex"),
    value.sha256,
  );
}
const s = humanPrivateGovernanceHistory.sources;
export const historicalHumanApp = historicalSubjectApp;
export const historicalPrivateApp = s.privateApp!.raw;
export const historicalCreationClient =
  objectGovernanceHistory.sources.client!.raw;
function readHistory(path: URL | string) {
  const value = path instanceof URL ? path.pathname : path;
  const files: Record<string, string> = {
    "/fixed-history/application/apps/web/src/features/creation/CreateDialog.tsx":
      s.humanFeature!.raw,
    "/fixed-history/application/apps/web/src/client.ts":
      historicalCreationClient,
    "/fixed-history/application/apps/web/src/local-preferences.ts":
      s.storage!.raw,
    "/fixed-history/application/apps/web/src/host/private-project-conversation-scope.ts":
      s.privateOwner!.raw,
  };
  assert.ok(
    Object.hasOwn(files, value),
    "only exact immutable historical operand reads",
  );
  return files[value]!;
}
function run(
  key: string,
  bindings: Record<string, unknown>,
): Record<string, unknown> {
  const module = { exports: {} };
  const value = s[key]!;
  const code = transformSync(value.raw, {
    loader: "ts",
    format: "cjs",
    target: "es2022",
    define: {
      "import.meta.url": JSON.stringify(
        "file:///fixed-history/application/" + value.path,
      ),
    },
  }).code;
  new Function("require", "module", code)((name: string) => {
    assert.ok(
      Object.hasOwn(bindings, name),
      "closed immutable historical dependency " + name,
    );
    return bindings[name];
  }, module);
  return module.exports;
}
const common = {
  "node:assert/strict": assert,
  "node:crypto": { createHash },
  "node:fs": { readFileSync: readHistory },
  "typescript/unstable/sync": { API },
  "typescript/unstable/fs": { createVirtualFileSystem },
  "typescript/unstable/ast": ast,
};
export const historicalHumanCreation = run("humanHelper", {
  ...common,
  "./object-annotations-consumption.js": historicalObjectAnnotations,
}) as Pick<
  typeof import("./human-creation-consumption.js"),
  | "humanCreationFixed"
  | "inverseHumanCreationFeature"
  | "assertHumanCreationWholeApp"
>;
export const historicalPrivateProjectScope = run("privateHelper", {
  ...common,
  "./human-creation-consumption.js": historicalHumanCreation,
}) as Pick<
  typeof import("./private-project-conversation-scope-consumption.js"),
  | "privateProjectScopeFixed"
  | "privateProjectScopeActions"
  | "inversePrivateProjectConversationScope"
  | "assertPrivateProjectConversationWholeApp"
>;
// Only the independently fixed pre-Stage30 entry. This is not a claim of full
// Reference preparation execution. It cannot accept a live/current operand.
export function historicalReferenceEntry(text: string) {
  assert.ok(
    !text.includes("useExchangeReferencePreparationState") &&
      !text.includes("useExchangeReferencePreparationCommit"),
    "original fixed no-preparation guards",
  );
  return text;
}
assert.equal(
  historicalHumanCreation.assertHumanCreationWholeApp(historicalHumanApp),
  s.privateApp!.raw,
  "full original Human restoration equals complete actual Git778",
);
const restored =
  historicalPrivateProjectScope.assertPrivateProjectConversationWholeApp(
    historicalPrivateApp,
  );
assert.equal(
  Buffer.byteLength(restored),
  historicalPrivateProjectScope.privateProjectScopeFixed.appBytes,
);
assert.equal(
  createHash("sha256").update(restored).digest("hex"),
  historicalPrivateProjectScope.privateProjectScopeFixed.appSHA256,
);
